type DiamondProps = {
  className?: string;
};

/**
 * The Work With Us diamond. Its stroke draws itself with scroll (scrub):
 * empty as the illustration enters at the bottom of the viewport, complete
 * once it reaches the middle. Phones and reduced-motion users get the
 * finished drawing (no scroll-linked motion there).
 */
export default function Diamond({ className }: DiamondProps) {
  const ref = useRef<HTMLSpanElement>(null);
  const reduceMotion = useReducedMotion();
  const enabled = useIsTabletUp() && !reduceMotion;
  const { scrollYProgress } = useScroll({
    target: ref,
    offset: ['start end', 'center center'],
  });
  const pathLength = useTransform(scrollYProgress, [0, 1], [0, 1]);

  return (
    // useScroll tracks an HTML element, so the ref sits on a wrapper.
    <span ref={ref} className={className} aria-hidden>
      <svg viewBox="0 0 118 118" fill="none" className="block size-full">
        <m.path
          d={PATH}
          stroke="#003544"
          strokeWidth={0.832696}
          strokeMiterlimit={10}
          style={{ pathLength: enabled ? pathLength : 1 }}
        />
      </svg>
    </span>
  );
}
